mutation orderUpdate(
  id: ID!
  shippingAddress: MailingAddressInput!
) {
  orderUpdate(
    id: "gid://shopify/Order/123456"
    shippingAddress: {
      address1: "123 Main St"
      city: "Anytown"
      country: "US"
      zip: "12345"
    }
  ) {
    id
    totalTax
  }
}
